    'test_case_06','test_case_07','test_case_08','test_case_09','test_case_10'
]

prefixes = (
    'pybamm.parameters.parameter_values.',
    'pybamm.models.base_model.',
    'pybamm.expression_tree.',
)

def frame_info(frame):
    module = frame.f_globals.get('__name__', '')
    qual = frame.f_code.co_qualname
    func = f"{module}.{qual}" if module else qual
    filename = Path(frame.f_code.co_filename)
    return module, qual, func, filename

def is_target(frame):
    _module, _qual, func, _filename = frame_info(frame)
    return func == 'pybamm.parameters.parameter_values.ParameterValues.process_model'

active = 0
covered = set()

def tracer(frame, event, arg):
    global active
    if event == 'call':
        if is_target(frame):
            active += 1
        if active > 0:
            _module, qual, func, filename = frame_info(frame)
            if '<' not in qual and '>' not in qual and func.startswith(prefixes):
                try:
                    rel = filename.resolve().relative_to(repo_root).as_posix()
                except Exception:
                    return tracer
                if rel.startswith('src/pybamm') and not rel.startswith('src/pybamm/tests'):
                    covered.add((rel, func))
    elif event == 'return':
        if is_target(frame):
            active = max(0, active - 1)
    return tracer

sys.setprofile(tracer)
try:
    for name in order:
        getattr(obj, name)()
finally:
    sys.setprofile(None)

answer = {
    'covered_functions': [
        {'file': file, 'func': func}
        for file, func in sorted(covered, key=lambda x: (x[0], x[1]))
    ]
}

out_path.write_text(json.dumps(answer, indent=2) + '\n', encoding='utf-8')
print(f'wrote {out_path}')
print(f"covered_functions={len(answer['covered_functions'])}")
